import XCTest

/// Device/simulator harness entry point for the production renderer benchmark.
/// Its assertion proves the report was generated by the launched app and that
/// the benchmark's structural/correctness checks passed before timing data is
/// accepted by an external analyzer.
final class NativeReconcileBenchmarkTests: XCTestCase {
    func testNativeReconcileReport() {
        let app = XCUIApplication()
        app.launchEnvironment["VOYAGER_NATIVE_RECONCILE_BENCH_FRAMES"] = "12"
        app.launchEnvironment["VOYAGER_NATIVE_RECONCILE_COMMIT_MODE"] = "dirty-label-commit"
        app.launch()

        let report = app.staticTexts["voyager-native-reconcile-benchmark-result"]
        XCTAssertTrue(report.waitForExistence(timeout: 20))
        XCTAssertTrue(report.label.contains("\"success\":true"), report.label)
        XCTAssertTrue(report.label.contains("\"frames\":12"), report.label)
        XCTAssertTrue(report.label.contains("\"commit_mode\":\"dirty-label-commit\""), report.label)
        XCTAssertTrue(report.label.contains("\"reconcile_ops_total\":12"), report.label)
        XCTAssertTrue(report.label.contains("\"structural_label_visits_total\":24"), report.label)
        XCTAssertTrue(report.label.contains("\"dynamic_label_updates_total\":12"), report.label)
    }
}
